// lib/src/mp_logger.dart
import 'package:logger/logger.dart';
import 'package:meta/meta.dart';

/// Enum representing the log levels for the Measurement Protocol Logger.
/// This enum is used to control the verbosity of the logs generated by the
/// [MPLogger] class.
enum MPLogLevel {
  /// Disables logging.
  none(Level.off),

  /// Logs all messages at the debug level.
  debug(Level.info),

  /// Logs only error messages.
  error(Level.error);

  const MPLogLevel(this.level);

  /// The [Level] associated with this log level.
  /// This is used by the [Logger] class to determine which messages to log.
  @internal
  final Level level;
}

@internal
class MPLogger {
  MPLogger(MPLogLevel level)
    : _logger = Logger(
        level: level.level,
        printer: PrettyPrinter(methodCount: 0),
      );

  final Logger _logger;

  void log(MPLogLevel level, String message) {
    _logger.log(level.level, message);
  }
}
